<script setup>
import QaRecipientEmailInbox from '../../components/messages/QaRecipientEmailInbox.vue';
import ClientAccessChoices from '../../components/guardian/ClientAccessChoices.vue';
import GuardianPaymentInsuranceTab from '../../components/guardian/GuardianPaymentInsuranceTab.vue';
import FamilyLedgerPanel from '../../components/billing/FamilyLedgerPanel.vue';
import SecureSessionCommentButton from '../../components/session-comments/SecureSessionCommentButton.vue';
import FamilySharingNotice from '../../components/session-comments/FamilySharingNotice.vue';
import SecureSessionCommentTip from '../../components/session-comments/SecureSessionCommentTip.vue';
import SecureSessionCommentHistory from '../../components/session-comments/SecureSessionCommentHistory.vue';
import {ref,computed,onMounted,nextTick,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';
import {AURICWELL_MARK_URL} from '../../constants/auricwellBrand';
import api from '../../services/api';import {useAuthStore} from '../../store/auth';import FamilyPortalShell from '../../components/portal/FamilyPortalShell.vue';
const audienceReviewNeeded=ref(false),audienceReviewed=ref(false);
const sharingNotice=ref(null),currentConversation=ref(null),conversationHistory=ref([]),conversationChoice=ref('current'),currentDraft=ref('');
const route=useRoute(),router=useRouter(),auth=useAuthStore();const profile=ref(null),choice=ref(''),panel=ref(['appointments','messages'].includes(route.query.panel)?route.query.panel:'home'),loading=ref(true),error=ref(''),appointments=ref([]),plan=ref(null),documents=ref(null),conversation=ref(null),messages=ref([]),draft=ref(''),sending=ref(false);let generation=0,messageScope='';
const choices=computed(()=>(profile.value?.agencies||[]).flatMap(a=>a.services.map(s=>({...s,agency:a,key:`${a.id}:${s.id}`}))));
const selected=computed(()=>choices.value.find(c=>c.key===choice.value));const params=computed(()=>({agencyId:selected.value?.agency.id,serviceId:selected.value?.id}));
const nav=computed(()=>[{key:'home',label:'My dashboard',icon:'dashboard'},{key:'appointments',label:'My appointments',icon:'appointments'},{key:'plan',label:'My plan',icon:'treatment'},{key:'documents',label:'My documents',icon:'documents'},{key:'messages',label:'Secure messages',icon:'messages'},{key:'access',label:'Access & independence',icon:'settings'},...(profile.value?.independent?[{key:'billing',label:'My billing & insurance',icon:'billing'}]:[]),{key:'security',label:'Account security',icon:'settings'},{key:'logout',label:'Sign out',icon:'account'}]);
const visibleAppointments=computed(()=>panel.value==='home'?appointments.value.filter(a=>new Date(a.startAt)>=new Date()).slice(0,3):appointments.value);
const title=computed(()=>nav.value.find(n=>n.key===panel.value)?.label||'My portal');
const when=a=>new Intl.DateTimeFormat('en-US',{dateStyle:'medium',timeStyle:'short',timeZone:a.timeZone||'America/Denver'}).format(new Date(a.startAt));
async function navigate(key){if(key==='logout'){await auth.logout('manual');return;}if(key==='security'){await router.push('/account-security');return;}panel.value=key;await loadSection();await nextTick();document.getElementById('family-portal-content')?.scrollIntoView({block:'start'});}
async function loadSection(){const run=++generation;const scope=panel.value==='messages'?`${profile.value?.clientId}:${choice.value}`:'';const preservedDraft=scope&&scope===messageScope?(conversation.value&&!conversation.value.readOnly?draft.value:currentDraft.value):'';messageScope=scope;loading.value=true;error.value='';conversation.value=null;currentConversation.value=null;conversationHistory.value=[];conversationChoice.value='current';currentDraft.value=preservedDraft;audienceReviewNeeded.value=false;audienceReviewed.value=false;messages.value=[];draft.value=preservedDraft;try{
 if(!selected.value)return;
 const options={params:params.value,skipGlobalLoading:true};
 if(['home','appointments'].includes(panel.value)){const r=await api.get('/dependent-portal/appointments',options);if(run===generation)appointments.value=r.data.appointments;}
 if(panel.value==='plan'){const r=await api.get('/dependent-portal/plan',options);if(run===generation)plan.value=r.data;}
 if(panel.value==='documents'){const r=await api.get('/dependent-portal/documents',options);if(run===generation)documents.value=r.data;}
 if(panel.value==='messages'){const [current,history]=await Promise.allSettled([api.post('/dependent-portal/conversation',params.value),api.get('/dependent-portal/conversation/history',options)]);if(run!==generation)return;
  if(history.status==='fulfilled')conversationHistory.value=history.value.data.threads||[];
  if(current.status==='fulfilled'){currentConversation.value={...current.value.data,readOnly:false};conversation.value=currentConversation.value;}
  else{error.value=current.reason?.response?.data?.error?.message||'The current shared conversation is unavailable. Authorized previous conversations remain read-only.';const previous=conversationHistory.value[0];if(previous){conversationChoice.value=String(previous.threadId||previous.thread_id);conversation.value={...previous,threadId:previous.threadId||previous.thread_id,readOnly:true};draft.value='';}}
  if(history.status==='rejected'&&current.status==='fulfilled')error.value=history.reason?.response?.data?.error?.message||'Previous conversations could not be opened. The current shared conversation is available.';
  await refreshMessages(run);}
 }catch(e){if(run===generation)error.value=e.response?.data?.error?.message||'Could not open this section. Please try again.';}finally{if(run===generation)loading.value=false;}}
async function refreshMessages(run=generation){if(!conversation.value)return;const id=conversation.value.threadId;try{const r=await api.get(`/dependent-portal/messages/${id}`,{skipGlobalLoading:true});if(run===generation&&conversation.value?.threadId===id)messages.value=r.data;}catch(e){if(run===generation&&conversation.value?.threadId===id&&[401,403].includes(e.response?.status)){messages.value=[];conversation.value=null;conversationHistory.value=conversationHistory.value.filter(t=>String(t.threadId||t.thread_id)!==String(id));if(String(currentConversation.value?.threadId)===String(id))currentConversation.value=null;}throw e;}}
async function chooseConversation(){const run=++generation;if(conversation.value&&!conversation.value.readOnly)currentDraft.value=draft.value;const previous=conversationHistory.value.find(t=>String(t.threadId||t.thread_id)===conversationChoice.value);conversation.value=conversationChoice.value==='current'?currentConversation.value:{...previous,threadId:previous?.threadId||previous?.thread_id,readOnly:true};draft.value=conversation.value?.readOnly?'':currentDraft.value;messages.value=[];error.value='';try{await refreshMessages(run);}catch(e){if(run===generation)error.value=e.response?.data?.error?.message||'This previous conversation could not be opened.';}}
async function send(){if(sending.value||(audienceReviewNeeded.value&&!audienceReviewed.value)||conversation.value?.readOnly||!draft.value.trim())return;const run=generation,id=conversation.value.threadId,text=draft.value;sending.value=true;try{if(!await sharingNotice.value?.ensureAcknowledged()||run!==generation)return;await api.post(`/dependent-portal/messages/${id}`,{body:text,expectedRecipientUserIds:(conversation.value.participants||[]).map(p=>Number(p.id||p.userId||p.user_id)).filter(id=>id>0&&id!==Number(auth.user?.id))});if(run===generation){draft.value='';await refreshMessages(run);}}catch(e){if(run===generation){if(['FAMILY_SHARED_AUDIENCE_REVIEW_REQUIRED','FAMILY_SHARED_AUDIENCE_CHANGED'].includes(e.response?.data?.error?.code)){try{const {data}=await api.post('/dependent-portal/conversation',params.value);if(run===generation){currentConversation.value={...data,readOnly:false};conversation.value=currentConversation.value;audienceReviewNeeded.value=true;audienceReviewed.value=false;error.value='The shared recipients changed. Review the updated list before sending your preserved draft.';}}catch{audienceReviewNeeded.value=true;audienceReviewed.value=false;error.value='The updated recipients could not be verified. Your draft is preserved; reopen the current shared conversation.';}}else error.value=e.response?.data?.error?.message||'Your message could not be sent.';}}finally{sending.value=false;}}
async function download(file){try{const r=await api.get(`/dependent-portal/documents/${file.id}`,{params:params.value,responseType:'blob'});const url=URL.createObjectURL(r.data),a=document.createElement('a');a.href=url;a.download=file.title;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{error.value='This document is no longer available. Please refresh.';}}
watch(()=>route.query.panel, value=>{if(['appointments','messages'].includes(value)&&panel.value!==value){panel.value=value;loadSection();}});
onMounted(async()=>{try{profile.value=(await api.get('/dependent-portal/me')).data;choice.value=choices.value[0]?.key||'';await loadSection();}catch(e){error.value=e.response?.data?.error?.message||'Your personal portal could not be opened.';loading.value=false;}});
</script>
<template><FamilyPortalShell :brand-name="selected?.kind==='tutoring'?selected?.agency.name:'AuricWell'" brand-subtitle="My personal portal" :logo-url="selected?.kind==='tutoring'?selected?.agency.logo:AURICWELL_MARK_URL" :agency-name="selected?.kind==='tutoring'?'':selected?.agency.name" :title="title" :user-name="profile?.name" :navigation="nav" :active="panel" account-key="security" @navigate="navigate"><template #context><label class="own-service" v-if="choices.length>1">My service<select v-model="choice" @change="loadSection"><option v-for="c in choices" :key="c.key" :value="c.key">{{c.agency.name}} · {{c.label}} · {{c.providerName}}</option></select></label></template>
<p v-if="loading" role="status">Opening your portal…</p><p v-if="error" class="error" role="alert">{{error}} <button @click="loadSection">Try again</button></p>
<template v-if="!loading&&profile"><section v-if="panel==='home'" class="personal-card"><h2>Welcome, {{profile.name.split(' ')[0]}}</h2><p>Your appointments, progress, and conversations in one place.</p><p v-if="selected?.providerName"><strong>{{selected.kind==='tutoring'?'Your tutor':'Your provider'}}:</strong> {{selected.providerName}}</p><p v-if="profile.schoolName">{{profile.schoolName}}</p><div class="quick"><button @click="navigate('messages')">Message {{selected?.providerName||'my team'}}</button><button @click="navigate('plan')">View my plan</button></div></section>
<section v-if="['home','appointments'].includes(panel)" class="personal-card"><h2>{{panel==='home'?'My upcoming appointments':'My appointments'}}</h2><p v-if="!visibleAppointments.length">No appointments are listed yet.</p><article v-for="a in visibleAppointments" :key="a.id" class="appointment"><strong>{{when(a)}}</strong><p>{{a.providerName}} · {{a.modality==='IN_PERSON'?'In person':'Virtual'}} · {{a.status.replaceAll('_',' ')}}</p><a v-if="a.joinUrl" :href="a.joinUrl">Join session →</a><SecureSessionCommentButton v-if="a.secureCommentsAvailable" :appointment-id="a.id" :client-id="profile.clientId" /><SecureSessionCommentTip v-if="a.secureCommentsAvailable" self :appointment-id="a.id" :start-at="a.startAt" :user-id="auth.user?.id" /></article></section>
<section v-if="panel==='plan'" class="personal-card"><h2>{{profile.name.split(' ')[0]}}’s plan</h2><p v-if="plan?.sharingPending">Your care team hasn’t shared a plan with your personal login yet.</p><p v-else-if="!plan?.hasActivePlan">Your plan will appear here when it is ready.</p><template v-else><h3>{{plan.plan?.title}}</h3><article v-for="(g,i) in plan.goals" :key="g.id" class="goal"><h3>Goal {{i+1}}: {{g.goalText}}</h3><p v-for="(o,j) in g.objectives" :key="o.id"><strong>Objective {{j+1}}:</strong> {{o.objectiveText}}</p></article></template></section>
<section v-if="panel==='documents'" class="personal-card"><h2>Shared with me</h2><p v-if="!documents?.files?.length">Documents your team shares directly with you will appear here.</p><button v-for="f in documents?.files||[]" :key="f.id" class="document" @click="download(f)">{{f.title}} · Download</button></section>
<ClientAccessChoices v-if="panel==='access'" @state="profile.independent=$event.status==='active'" /><section v-if="panel==='billing'&&profile.independent" class="personal-card"><GuardianPaymentInsuranceTab :agency-id="selected?.agency.id" :client-id="profile.clientId" :guardian-user-id="auth.user?.id" /><FamilyLedgerPanel :agency-id="selected?.agency.id" :client-id="profile.clientId" /></section>
<SecureSessionCommentHistory v-if="panel==='messages'" :client-id="profile.clientId" family /><QaRecipientEmailInbox v-if="panel==='messages'" /><section v-if="panel==='messages'&&conversation" class="personal-card"><h2>Secure care conversations</h2><label v-if="conversationHistory.length">Conversation<select v-model="conversationChoice" @change="chooseConversation"><option v-if="currentConversation" value="current">Current shared conversation</option><option v-for="thread in conversationHistory" :key="thread.threadId||thread.thread_id" :value="String(thread.threadId||thread.thread_id)">Previous conversation · read-only · {{thread.last_message_at ? new Date(thread.last_message_at).toLocaleDateString() : 'Retained history'}}</option></select></label><p class="audience">{{conversation.audience || (conversation.readOnly ? 'Previous conversation · original authorized recipients only' : 'Current shared family conversation')}}</p><ul v-if="conversation.participants?.length" aria-label="Conversation recipients"><li v-for="person in conversation.participants" :key="person.id||person.userId||person.user_id">{{person.name||person.displayName||[person.first_name,person.last_name].filter(Boolean).join(' ')||'Authorized participant'}}</li></ul><p v-if="conversation.readOnly">This previous conversation is read-only.<template v-if="currentConversation"> Choose the current shared conversation to send an update.</template><template v-else> Sending is unavailable until a current shared conversation can be opened.</template></p><button @click="refreshMessages()">Refresh messages</button><p v-if="!messages.length">{{conversation.readOnly ? 'No retained messages are available in this conversation.' : 'Start your conversation below.'}}</p><article v-for="m in messages" :key="m.id" class="message"><strong>{{Number(m.sender_user_id)===Number(auth.user?.id)?'You':conversation.providerName}}</strong><p>{{m.body}}</p></article><form v-if="!conversation.readOnly" @submit.prevent="send"><FamilySharingNotice ref="sharingNotice" :agency-id="selected?.agency.id" :scope-key="`${profile.clientId}:${selected?.agency.id}:${conversation.threadId}`" /><label v-if="audienceReviewNeeded"><input v-model="audienceReviewed" type="checkbox" /> I reviewed the updated shared recipients above.</label><label>Your message<textarea v-model="draft" maxlength="4000" rows="4" required /></label><button :disabled="sending||(audienceReviewNeeded&&!audienceReviewed)||!draft.trim()">{{sending?'Sending…':'Send secure message'}}</button></form></section></template></FamilyPortalShell></template>
<style scoped>.personal-card{padding:24px;background:white;border:1px solid #d4e0eb;border-radius:16px;margin:0 0 20px;color:#193653}.personal-card p{line-height:1.6}.own-service{display:grid;gap:5px;margin-top:12px;max-width:550px;font-size:13px}.own-service select,textarea{padding:12px;border:1px solid #bacddd;border-radius:8px;font:inherit;width:100%;box-sizing:border-box}.quick{display:flex;gap:12px;flex-wrap:wrap}button,.appointment a{font:inherit;padding:10px 14px;border:1px solid #285f91;border-radius:8px;background:#285f91;color:#fff;cursor:pointer}.appointment,.goal{padding:18px 0;border-top:1px solid #e1e8ef}.appointment a{display:inline-block;text-decoration:none}.message{padding:14px;background:#f1f6fb;border-radius:12px;margin:12px 0;white-space:pre-wrap}.audience{padding:12px;background:#edf6f2;border-radius:8px}.personal-card form label{display:grid;gap:8px;margin:14px 0}.document{display:block;margin:12px 0}.error{color:#a12222}button:disabled{opacity:.6}</style>
